package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                // PIC X len=1 = "N"
var WsLabel string = "                    " // PIC X(20) len=20 = SPACES (20 spaces)
var WsACount int64 = 0                    // PIC 99 len=2 = 0
var WsTotalA int64 = 0                    // PIC 999 len=3 = 0
var WsCount int64 = 0                     // PIC 999 len=3 = 0

// file handling
var partFile *os.File
var scanner *bufio.Scanner
var currentPartRec PartRec
var hasCurrent bool

func formatNumeric(v int64, width int) string {
	// unsigned zero-padded, truncate high-order digits
	// handle negative just in case
	neg := v < 0
	if neg {
		v = -v
	}
	s := strconv.FormatInt(v, 10)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	if neg {
		// COBOL would show sign, but not needed for this program
		// put '-' in front dropping one digit if needed
		if len(s) == width {
			s = "-" + s[1:]
		} else {
			s = "-" + s
		}
	}
	return s
}

func padRight(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func main() {
	MAIN_PARA()
}

func MAIN_PARA() {
	OPEN_INPUT_PART_FILE()
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	CLOSE_PART_FILE()
	SUMMARY_PARA()
}

func OPEN_INPUT_PART_FILE() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		if os.IsNotExist(err) {
			WsEofFlag = "Y"
			scanner = nil
			partFile = nil
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	partFile = f
	scanner = bufio.NewScanner(f)
	// allow long lines
	const maxCapacity = 10 * 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCapacity)
}

func CLOSE_PART_FILE() {
	if partFile != nil {
		partFile.Close()
	}
}

func READ_PARA() {
	if scanner == nil {
		WsEofFlag = "Y"
		hasCurrent = false
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		// COBOL LINE SEQUENTIAL: pad with spaces if shorter than record length
		// line from scanner has no newline, but trailing spaces are preserved except
		// scanner strips \r; we pad.
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		lbPart := line[0:8]
		lbRegion := line[8:11]
		sSerialStr := line[11:15]
		var serial int64
		trimmed := strings.TrimSpace(sSerialStr)
		if trimmed == "" {
			serial = 0
		} else {
			// keep only digits, but parse as integer
			// COBOL numeric field contains digits only
			v, err := strconv.ParseInt(trimmed, 10, 64)
			if err != nil {
				// if contains spaces or non-digit, treat as 0
				// try to extract digits
				digits := ""
				for _, c := range sSerialStr {
					if c >= '0' && c <= '9' {
						digits += string(c)
					}
				}
				if digits != "" {
					v, _ = strconv.ParseInt(digits, 10, 64)
					serial = v
				} else {
					serial = 0
				}
			} else {
				serial = v
			}
		}
		currentPartRec = PartRec{
			LbPart:   lbPart,
			LbRegion: lbRegion,
			LbSerial: serial,
		}
		hasCurrent = true
		WsEofFlag = "N"
	} else {
		// check scanner error
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
		hasCurrent = false
	}
}

func PROCESS_PARA() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	// LB-PART is X(8) in current record
	lbPart := currentPartRec.LbPart
	cnt := strings.Count(lbPart, "A")
	WsACount = int64(cnt)
	// apply truncation to PIC 99 (though count max 8 fits)
	if WsACount > 99 {
		// keep low-order digits: e.g., 100 -> 0
		s := strconv.FormatInt(WsACount, 10)
		if len(s) > 2 {
			s = s[len(s)-2:]
			v, _ := strconv.ParseInt(s, 10, 64)
			WsACount = v
		}
	}

	// STRING ... INTO WS-LABEL
	// Build sources
	// LB-REGION DELIMITED BY SPACE
	srcRegion := currentPartRec.LbRegion
	idx := strings.Index(srcRegion, " ")
	var effRegion string
	if idx >= 0 {
		effRegion = srcRegion[:idx]
	} else {
		effRegion = srcRegion
	}
	srcDash := "-"
	effDash := srcDash // SIZE
	srcPart := currentPartRec.LbPart
	idx2 := strings.Index(srcPart, " ")
	var effPart string
	if idx2 >= 0 {
		effPart = srcPart[:idx2]
	} else {
		effPart = srcPart
	}
	// LB-SERIAL DELIMITED BY SIZE -> formatted as PIC 9(4) zero-padded
	serialFormatted := formatNumeric(currentPartRec.LbSerial, 4)
	effSerial := serialFormatted // SIZE = 4

	// concatenate into target of 20 spaces
	parts := []string{effRegion, effDash, effPart, effDash, effSerial}
	// perform STRING copy semantics with overflow truncation
	target := []byte(strings.Repeat(" ", 20))
	pos := 0
	for _, p := range parts {
		for i := 0; i < len(p) && pos < 20; i++ {
			target[pos] = p[i]
			pos++
		}
		// if pos >=20 stop
		if pos >= 20 {
			break
		}
	}
	WsLabel = string(target)

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = WsTotalA + WsACount
	// truncate to PIC 999 (keep low-order 3 digits)
	if WsTotalA > 999 || WsTotalA < -999 {
		s := strconv.FormatInt(WsTotalA, 10)
		neg := false
		if strings.HasPrefix(s, "-") {
			neg = true
			s = s[1:]
		}
		if len(s) > 3 {
			s = s[len(s)-3:]
		}
		v, _ := strconv.ParseInt(s, 10, 64)
		if neg {
			v = -v
		}
		WsTotalA = v
	}
	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	if WsCount > 999 {
		s := strconv.FormatInt(WsCount, 10)
		if len(s) > 3 {
			s = s[len(s)-3:]
			v, _ := strconv.ParseInt(s, 10, 64)
			WsCount = v
		}
	}

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20) -> exactly 20 chars
	// " A=" literal
	// WS-A-COUNT is PIC 99 -> zero-padded 2 digits
	outACount := formatNumeric(WsACount, 2)
	// WsLabel already 20 chars
	fmt.Fprintf(os.Stdout, "%s A=%s\n", WsLabel, outACount)

	// PERFORM READ-PARA
	READ_PARA()
}

func SUMMARY_PARA() {
	// DISPLAY "LABELS: " WS-COUNT " A-TOTAL: " WS-TOTAL-A.
	outCount := formatNumeric(WsCount, 3)
	outTotal := formatNumeric(WsTotalA, 3)
	fmt.Fprintf(os.Stdout, "LABELS: %s A-TOTAL: %s\n", outCount, outTotal)
}
